12	type Recorder = {
13	  transport: WorkerTransport;
14	  deltas: Array<{
15	    delta: string;
16	    isFullReplacement?: boolean;
17	    isFinal?: boolean;
18	  }>;
19	  errors: Array<{
20	    message: string;
21	    code?: string;
22	    context?: AgentErrorContext;
23	  }>;
