26	function makeTransport(): Recorder {
27	  const deltas: Recorder["deltas"] = [];
28	  const errors: Recorder["errors"] = [];
29	  const noop = () => undefined;
30	  const asyncNoop = async () => undefined;
31	  const transport: WorkerTransport = {
32	    setJobId: noop,
33	    async sendStreamDelta(delta, isFullReplacement, isFinal) {
34	      deltas.push({ delta, isFullReplacement, isFinal });
35	    },
36	    signalDone: asyncNoop,
37	    signalCompletion: asyncNoop,
38	    async signalError(error, errorCode, context) {
39	      errors.push({ message: error.message, code: errorCode, context });
40	    },
41	    sendStatusUpdate: asyncNoop,
42	    sendCustomEvent: asyncNoop,
43	  };
44	  return { transport, deltas, errors };
45	}
