test("recognizes a quota exhaustion phrased with intervening words", () => {
  // Captured live 2026-08-05 from Alibaba's Token Plan endpoint
  // (token-plan.ap-southeast-1.maas.aliyuncs.com), HTTP 429. The old pattern
  // required "quota exhausted" ADJACENT, so "quota has been exhausted" fell
  // through to undefined — no health mark and, worse, no park, which is the
  // exact one-failed-run-per-tick pathology #2521 removed for z.ai.
  expect(
    classifyError(
      new Error(
        "Your token-plan 5-hour quota has been exhausted. The quota will reset at 08-05 18:02:00 UTC."
      )
    )
  ).toBe("PROVIDER_QUOTA_EXHAUSTED");
  // Sibling phrasings that the adjacency requirement also dropped.
  expect(classifyError(new Error("Your quota was exceeded."))).toBe(
    "PROVIDER_QUOTA_EXHAUSTED"
  );
  expect(classifyError(new Error("monthly quota is exhausted"))).toBe(
    "PROVIDER_QUOTA_EXHAUSTED"
  );
  // Must NOT swallow an unrelated sentence that merely contains both words
  // far apart.
  expect(
    classifyError(
      new Error(
        "quota settings saved; the deployment pipeline exhausted its retries"
      )
    )
  ).toBeUndefined();
});

